import * as THREE from 'three';

// Generated by tools/materials/volcanic-object-prepare.py. Source material math and
// renderer mappings are deliberately recorded separately in the asset document.
export const VOLCANIC_OBJECT_GLSL = "// Original PS 750135c350. Texture channels are used exactly as sampled.\nstruct VolcanicObjectSurface {\n  vec3 color;\n  vec3 baseTangentNormal;\n  vec3 metalTangentNormal;\n  vec3 fabricTangentNormal;\n  float detailMix;\n  float smoothness;\n  float metalness;\n  float broadenedSpecularScale;\n};\nVolcanicObjectSurface sampleVolcanicObject(vec2 uv, vec4 cb[4],\n    sampler2D baseMap, sampler2D normalMap, sampler2D metalDetailMap, sampler2D fabricDetailMap) {\n  vec4 metalDetail = texture2D(metalDetailMap, uv * cb[0].xy);\n  vec4 fabricDetail = texture2D(fabricDetailMap, uv * cb[1].xy);\n  vec4 base = texture2D(baseMap, uv);\n  vec4 normal = texture2D(normalMap, uv);\n  float detailAlpha = fabricDetail.a + base.a * (metalDetail.a - fabricDetail.a);\n  VolcanicObjectSurface result;\n  result.color = 2.0 * base.rgb * cb[2].x * detailAlpha;\n  result.smoothness = 2.0 * normal.a * detailAlpha;\n  result.metalness = 2.0 * base.a * detailAlpha;\n  result.baseTangentNormal = normal.rgb * 2.0 - 1.0;\n  result.metalTangentNormal = metalDetail.rgb * 2.0 - 1.0;\n  result.fabricTangentNormal = fabricDetail.rgb * 2.0 - 1.0;\n  result.detailMix = base.a;\n  result.broadenedSpecularScale = cb[3].x;\n  return result;\n}\n// The native TBN maps each vector BEFORE its individual normalization.\n// Keep the sum unnormalized for SH; normalize only the eventual surface normal.\nvec3 volcanicObjectPrelightingNormal(mat3 worldFrame, VolcanicObjectSurface surface) {\n  vec3 baseWorld = normalize(worldFrame * surface.baseTangentNormal);\n  vec3 metalWorld = normalize(worldFrame * surface.metalTangentNormal);\n  vec3 fabricWorld = normalize(worldFrame * surface.fabricTangentNormal);\n  return baseWorld + fabricWorld + surface.detailMix * (metalWorld - fabricWorld);\n}\n";
const ROLES = ['base','normal','metalDetail','fabricDetail'];

export async function prepareRecoveredVolcanicObjectMaterials(document, manager) {
  if (!document?.materials?.length) return { apply() {}, applied: 0, provenance: null };
  const loader = new THREE.TextureLoader(manager), textures = new Map();
  const sources = new Map(Object.values(document.sourceTextures).map(row => [row.url, row]));
  const urls = [...new Set(document.materials.flatMap(row => Object.values(row.textures)))];
  // Bound decoder work while loading the shared textures once per document.
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(4, urls.length) }, async () => {
    while (next < urls.length) {
      const url = urls[next++], source = sources.get(url);
      if (!source) throw new Error(`Missing VolcanicObject texture provenance: ${url}`);
      const texture = await loader.loadAsync(url);
      texture.colorSpace = source.colorSpace === 'srgb' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
      texture.flipY = false;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textures.set(url, texture);
    }
  }));
  const recipes = new Map(document.materials.map(row => [`${row.assetId}/${row.materialId}`, row]));
  let applied = 0;
  return {
    provenance: { evidenceId: document.evidenceId, sections: recipes.size, textures: textures.size, runtimeMapping: document.runtimeMapping, limitations: document.limitations },
    get applied() { return applied; },
    dispose() { for (const texture of textures.values()) texture.dispose(); },
    apply(gltf, asset) {
      gltf.scene.traverse(mesh => {
        if (!mesh.isMesh) return;
        for (const material of [].concat(mesh.material)) {
          if (material.userData.recoveredVolcanicObjectShader) continue;
          const recipe = recipes.get(`${asset.id}/${material.userData.sourceMaterialId}`);
          if (!recipe) continue;
          if (!mesh.geometry.getAttribute('uv')) throw new Error(`Source VolcanicObject mesh has no UV0: ${asset.id}/${recipe.materialId}`);
          material.color.setRGB(1, 1, 1);
          material.roughness = 1;
          // Native ordinary ID0; shader supplies raw source metalness below.
          material.metalness = 0;
          material.map = material.normalMap = material.roughnessMap = material.metalnessMap = material.aoMap = material.emissiveMap = null;
          material.emissive?.setRGB(0, 0, 0);
          material.userData.recoveredVolcanicObjectShader = { evidenceId: document.evidenceId, sourceShader: recipe.sourceShader, runtimeMapping: document.runtimeMapping, nativeLightingInputs: document.nativeLightingInputs };
          material.userData.placeholder = false;
          material.userData.neutralColorApproximation = false;
          material.onBeforeCompile = function(shader) {
            for (const role of ROLES) shader.uniforms[`bf2_volcanic_object_${role}`] = { value: textures.get(recipe.textures[role]) };
            shader.uniforms.bf2_volcanic_object_cb = { value: recipe.constants.map(v => new THREE.Vector4(...v)) };
            shader.vertexShader = `varying vec2 bf2_volcanic_object_uv;
              varying vec3 bf2_volcanic_object_world;
            ` + shader.vertexShader;
            shader.vertexShader = shader.vertexShader.replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
              vec4 bf2_volcanic_object_wp = vec4(transformed, 1.0);
              #ifdef USE_INSTANCING
                bf2_volcanic_object_wp = instanceMatrix * bf2_volcanic_object_wp;
              #endif
              bf2_volcanic_object_world = (modelMatrix * bf2_volcanic_object_wp).xyz;
              bf2_volcanic_object_uv = uv;
            `);
            shader.fragmentShader = `varying vec2 bf2_volcanic_object_uv;
              varying vec3 bf2_volcanic_object_world;
              uniform vec4 bf2_volcanic_object_cb[4];
              ${ROLES.map(role => `uniform sampler2D bf2_volcanic_object_${role};`).join('\n')}
              ${VOLCANIC_OBJECT_GLSL}
              // Derivative frame is a documented renderer boundary; source
              // normal composition and native frame publication are separate.
              mat3 bf2_volcanic_object_tbn(vec3 position, vec3 n, vec2 uvValue) {
                vec3 q0 = dFdx(position), q1 = dFdy(position);
                vec2 st0 = dFdx(uvValue), st1 = dFdy(uvValue);
                vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
                vec3 tangent = q1perp * st0.x + q0perp * st1.x;
                vec3 bitangent = q1perp * st0.y + q0perp * st1.y;
                float invmax = inversesqrt(max(max(dot(tangent, tangent), dot(bitangent, bitangent)), 1e-16));
                return mat3(tangent * invmax, bitangent * invmax, n);
              }
            ` + shader.fragmentShader;
            shader.fragmentShader = shader.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
              VolcanicObjectSurface bf2_volcanic_object_surface = sampleVolcanicObject(bf2_volcanic_object_uv,
                bf2_volcanic_object_cb,
                ${ROLES.map(role => `bf2_volcanic_object_${role}`).join(', ')});
              diffuseColor.rgb = bf2_volcanic_object_surface.color;
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <emissivemap_fragment>', 'totalEmissiveRadiance = vec3(0.0);');
            shader.fragmentShader = shader.fragmentShader.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
              roughnessFactor = 1.0 - clamp(bf2_volcanic_object_surface.smoothness, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <metalnessmap_fragment>', `#include <metalnessmap_fragment>
              metalnessFactor = bf2_volcanic_object_surface.metalness;
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_maps>', `
              mat3 bf2_volcanic_object_frame = bf2_volcanic_object_tbn(-vViewPosition, normal, bf2_volcanic_object_uv);
              vec3 bf2_volcanic_object_baseWorld = inverseTransformDirection(bf2_volcanic_object_frame * bf2_volcanic_object_surface.baseTangentNormal, viewMatrix);
              vec3 bf2_volcanic_object_metalWorld = inverseTransformDirection(bf2_volcanic_object_frame * bf2_volcanic_object_surface.metalTangentNormal, viewMatrix);
              vec3 bf2_volcanic_object_fabricWorld = inverseTransformDirection(bf2_volcanic_object_frame * bf2_volcanic_object_surface.fabricTangentNormal, viewMatrix);
              vec3 bf2_volcanic_object_prelightingNormal = bf2_volcanic_object_baseWorld + bf2_volcanic_object_fabricWorld + bf2_volcanic_object_surface.detailMix * (bf2_volcanic_object_metalWorld - bf2_volcanic_object_fabricWorld);
              normal = transformDirection(bf2_volcanic_object_prelightingNormal, viewMatrix);
            `);
          };
          material.customProgramCacheKey = function(){return 'bf2-source-SS_ObjectPreset_01-750135c350-v1|derivative-frame';};
          material.needsUpdate = true;
          applied++;
        }
      });
    },
  };
}
